    "title": "Abbat Faria",
    "category": "Adabiyot",
    "body": "Aleksandr Dyumaning “Graf Monte-Kristo”(1845) romanidagi asosiy qahramonlardan biri. U If qalʼasida mahbus bo’lib, u yerda bosh qahramon Edmond Dantes bilan uchrashadi. Abbat Edmondning ustozi va do’stiga aylanadi. Abbat Faria haqiqatan ham mavjud bo’lgan inson asosida yaratilgan. Aslida, Abbat Faria(1756–1819) tarixiy shaxs bo’lib, portugal katolik ruhoniysi, faylasuf va olim edi. Uning nomi gipnoz sohasi bilan bog’liq,u bu hodisani ilmiy nuqtai nazardan o’rgangan birinchi olimlardan biri hisoblanadi. Lekin badiiy obraz haqiqiy shaxsdan ancha farq qiladi",
