    "category": "Fan",
    "body": "Norvegiya hukumati tomonidan ta’sis etilgan matematika yo’nalishi bo’yicha topshiriluvchi mukofot 2003-yildan boshlab tashkil etilgan mukofot mashxur norveg matematigi Nils Xenrik Abel sharafiga nomlamgan. Sovrin puli miqdori Nobel mukofotiga nisbatan teng bo’lib, 2024- yil holatiga 754.000 $ ni tashkil etadi. Alfred Nobel o’zi nomidagi mukofotni matematikga berilishini taqiqlaganidan keyin, Sofus Li alohida mukofot joriy etishni taklif qiladi. 1902 yilda – Abel tavalludining 100 yilligiga bag’ishlab, birinchi sovrindorlar ismi ma’lum qilinishi rejada edi, lekin tashkiliy ishlar sababli 2003 yilda ilk sovrindorlar nomi ma’lum qilingan",
