    "title": "Adrian devori",
    "category": "Tarix",
    "body": "Buyuk Britaniyaning shimoliy qismida joylashgan. Milodiy 122–128-yillarda Rim imperatori Hadrian buyrug’i bilan qurilgan. Devorning uzunligi 117 km bo’lib, u Irlandiya dengizidan Shimoliy dengizgacha cho’zilgan. Mustahkam tosh va torfdan qurilgan bu inshoot Rim imperiyasining shimoliy chegarasini himoya qiluvchi eng yirik mudofaa tizimlaridan biri bo’lgan. Adrian devori bo’ylab qal’alar, minoralar va harbiy garnizonlar joylashtirilgan. U nafaqat harbiy maqsad, balki Rim hukmronligini ramziy jihatdan mustahkamlash vazifasini ham bajargan. Bugungi kunda Adrian devori Britaniyaning eng mashhur tarixiy yodgorliklaridan biri bo’lib, UNESCO Butunjahon merosi ro’yxatiga kiritilgan",
