    "title": "Akupunktura",
    "category": "Fan",
    "body": "organizmning yumshoq toʻqimalariga maxsus ignalar kiritib davolash. Reflektor terapiya usullaridan biri Xitoy, Koreya, Yaponiya xalq tibbiyotida igna sanchib davolash qadimdan maʼlum. Bunda gavdaning muayyan (700 ga yaqin) nuqtalariga kiritilgan ignalar nerv uchlarini taʼsirlaydi. Taʼsirlanish bosh yoki orqa miyaga, u yerdan turli aʼzolarga oʻtadi. Periferik nerv sistemasi kasalliklari, uyqu buzilishi, moddalar almashinuvining oʻzgarishi, shikastlanish va boshqalar natijasida paydo boʻladigan boʻgʻim va muskul kasalliklarida qoʻllanadi. Zarurat tugʻilganda igna sanchib davolash bilan birga dori-darmonlar ham buyuriladi",
