    "title": "Aleksandr Greyam Belll",
    "category": "Texnologiya",
    "body": "Shotland-amerikalik olim, ixtirochi va pedagog. Amalda foydalanish uchun yaroqli birinchi telefon uchun 1876-yilda patent olgan. Energiya yoki quvvatlar nisbati logarifmi bilan oʻlchanadigan birlik – Bell nomi bilan atalgan. Onasining eshita olishida bo’lgan va otasi nutq ilmi bilan shug’ullangan. U yoshligidan tovush, nutq va eshitish tizimlariga qiziqqan va eshitish bilan bog’liq muammolarni o’rgangan va karlar ta’limi yo’nalishida ham faol ishlagan. Telefon uchun patent hozirgi kunda Antonio Meuchchiga tegishli. 2002 yilda AQSh kongressi patent unga tegishli ekanini e’lon qilgan",
