    "title": "Alkatraz qamoqxonasi",
    "category": "Tarix",
    "body": "Alkatraz oroli, ko’pincha “Qoya” deb ham ataladi, fuqarolar urushi davrida harbiy qamoqxona, keyin esa federal jazoni ijro etish muassasasi sifatida xizmat qilgan. Qamoqxonaning sovuq va notinch dengiz suvlari boʻyida joylashgani qochishni deyarli imkonsiz qiladi. 1963 yilda qamoqxona yopiladi va Alkatraz Oltin darvoza milliy dam olish maskanining bir qismiga aylandi. Hozirda ushbu joy qamoqxona kameralarini o’rganuvchi, qochishga urinish haqidagi hikoyalarni eshitadigan va orolning xilma-xil tarixini qadrlaydigan tashrif buyuruvchilarni o’ziga jalb qiladi. Bundan tashqari, Alkatraz G’arbiy sohildagi eng qadimgi ishlaydigan mayoqqa ega va dengiz qushlari uchun uya vazifasini bajaradi",
