    "body": "Orzular ortidan quvish fojeasi. Frensis Skott Fitsjerald tomonidan yozilgan roman 1920-yillar «Jazz asri» davrini tasvirlaydi. Asarda boylik, hashamat, yolg’on muhabbat va soxta orzular olamida yashayotgan insonlar hayoti ko’rsatiladi. Getsbi – sirli va nihoyatda boy inson, u oddiy yigitlik paytida sevgan ayoli, Dayzi Byukenanga yetishish uchun jamiyat zinapoyasidan shiddat bilan yuqorilaydi. Butun hayotini o’zgartiradi, faqat bir maqsad – Dayzini qaytarish uchun. Ammo asar so’ngida olinadigan xulosa: orzular har doim ham haqiqat bilan mos kelavermaydi. Getsbining orzusi qulab tushadi va bu orzular qulashida jamiyatdagi ikkiyuzlamachilik, boylar hamda kambag’allar o’rtasidagi tafovut, shuningdek, o’tmishni qaytarish ilinjida yashashning xavflari yotadi",
