    "category": "San’at",
    "body": "Mikelanjelo tomonidan 1501–1504-yillarda yaratilgan haykal. Renessans davrining san’at durdonasi hisoblanadi. Haykal Injildagi Dovud payg’ambarning Goliafga qarshi jangidan oldingi holatini tasvirlaydi. Haykal balandligi 5.17 metr. Verrokkio haykal yasashda yosh Leonardo da Vincidan ilhomlangan degan farazlar mavjud. Mikelanjelo yosh Dovudni mukammal erkak tanasi andozasida tasvirlab, insonning anatomik tuzilishini nihoyatda aniq ko’rsatgan. Asar dastlab Florensiyadagi shaharning markaziy maydoniga qo’yilgan, hozirda esa Uffizi galereyasining bir qismi bo’lgan Akkademiya galereyasida saqlanadi",
