    "body": "Ushbu ibora miloddan avvalgi 69-yil Rim imperatori sifatida taxtga ko’tarilgan Avl Vitelliyga tegishli. Vitelliy taxtni egallashidan biroz oldin Mark Salviy Oton imperator deb e’lon qilingan edi. Imperatorlik taxti uchun o’rtada bo’lgan ayovsiz jangda Mark Salviy Oton qo’shinlari qirib tashlanadi. O’liklarga to’la jang maydonini kuzatib, Avl Vitelliy bepisandlik bilan “Dushman murdasi xushbo’y hid taratadi” degan. Bu voqealarni Gay Svetoniy Trankvill “O’n ikki Sezarning hayoti” asarida yozib qoldirgan",
