    "title": "Eduard Kammings",
    "category": "Adabiyot",
    "body": "— 1894-yil 14-oktabrda Massachusets shtatining Kembrij shahrida tug’ilgan. U grammatika va punktuatsiya qoidalarini buzib, she’riyatda inqilob qilgan amerikalik shoir va rassom. U asosan kichik harflar bilan yozishi va so’zlarni qog’ozda vizual shaklga solishi bilan tanilgan. “i carry your heart with me” eng mashhur sheʼri. Kammings o’zini birinchi navbatda rassom, keyin shoir deb hisoblagan. U hayoti davomida 1600 dan ortiq moybo’yoqli rasm va minglab chizmalar yaratgan. Birinchi jahon urushida asirlikda bo’lgani uning “The Enormous Room” asariga asos bo’lgan. Uning ijodi lirik sevgi va o’tkir ijtimoiy satira uyg’unligidir",
