    "category": "Texnologiya",
    "body": "braziliyalik-amerikalik internet tadbirkor va investor, Eduardo Saverin Facebook’ning hammuassislaridan biri. Tug’ilgan: 19-mart 1982-yil, San-Paulu, Braziliya. Ta’limi: Harvard universitetida iqtisodiyot bo’yicha tahsil olgan. Facebook: 2004-yilda Mark Zuckerberg bilan birga Facebook’ni tashkil qilgan. Dastlab kompaniyaning moliyaviy ishlarini yuritgan va CFO sifatida faoliyat olib borgan. Zuckerberg bilan nizosi: Keyinchalik uning kompaniyadagi ulushi keskin kamaygan. Saverin Zuckerberg va boshqa hamkorlarini sudga bergan; ish 2009-yilda kelishuv bilan yakunlangan. The Social Network: 2010-yilgi filmda uning obrazi Andrew Garfield tomonidan ijro etilgan. Keyingi faoliyati: Venchur investor sifatida texnologik startaplarga sarmoya kiritgan. B Capital: 2015-yilda Raj Ganguly bilan B Capital Group investitsiya firmasini tashkil qilgan. Fuqaroligi: Braziliya va AQSh bilan bog’liq bo’lgan; 2011-yilda AQSh fuqaroligidan voz kechgan. Boyligi: Uning boyligi asosan Facebook aksiyalari va keyingi investitsiyalaridan shakllangan. Forbes uni dunyoning eng boy texnologiya tadbirkorlari qatorida qayd etadi. Qiziq fakt: Saverin Facebook’ning dastlabki davridagi eng muhim moliyaviy hamkorlardan biri bo’lgan, ammo kompaniyaning keyingi rivojlanishida Zuckerberg bilan munosabatlari keskin yomonlashgan",
