    "body": "(21.09.1872, Varshava - 17.01.1945, Skernevitse) — polyak rassomi. Yan Mateyko va Isidor Yablonskiy kabi mashxur rassomlardan saboq olgan. Ikkinchi jahon urushi vaqtida yuz bergan Varshava qo’zg’oloni vaqtida Skernevitsega ko’chib o’tgan rassom 1945-yil ushbu shaharni ozod qilish uchun kelgan 1-beloruss fronti jangchilaridan birining daydi o’qidan vafot etgan. Rassomning mashxur kartinalaridan biri - siz yuqorida ko’rib turgan “Paganinining o’limi” kartinasi. Unda mashxur pianinochi haqida tarqalgan mashxur afsonaga murojaat qilingan va o’lim oldidan u uchun so’nggi musiqani chalayotgan iblis tasvirlangan",
