    "category": "Boshqa",
    "body": "Ispaniyaning Pamplona shahrida har yili o’tkaziladigan an’anaviy buqalardan qochish marosimi. San Fermin bayrami doirasida bo’lib o’tadigan bu hodisada odamlar ertalab soat 08:00 da 6 ta buqadan qochib 875 metrli tor ko’cha bo’ylab yugurishadi. Avvaliga buqalarni arenaga olib borish usuli sifatida paydo bo’lgan ushbu marosimni qaysidir ma’noda korridaning kirish qismi, deyilsa bo’ladi. Ernest Xemingueyning «Quyosh chiqaveradi» asari va boshqa koʻplab filmlar ham aynan San Fermin va ensyerro voqealari asosida yaratilgan",
