    "title": "EPITAFIYA",
    "category": "Adabiyot",
    "body": "Qabr toshiga bitilgan yodgorlik yozuvi yoki marhum xotirasiga bag’ishlangan qisqa she’riy asar. Odatda epitafiya marhumning hayot yo’li, uning fazilatlari yoki o’limidan keyingi falsafiy mushohadalar haqida bo’ladi. Qadimda bu janr she’riyatning bir turi sifatida shakllangan bo’lib, hozirda nafaqat adabiy asar, balki madaniy-tarixiy yodgorlik hisoblanadi. Epitafiyalar qisqa, ammo o’ta ta’sirli va mazmunli bo’lishi bilan ajralib turadi. Qiziqarli tomoni shundaki, ko’p mashhur insonlar o’z epitafiyalarini hayotlik chog’larida yozib qoldirishgan. Masalan, Uilyam Shekspirning qabr toshida uning suyaklariga tegmaslik haqida ogohlantirish yozilgan bo’lsa, buyuk fizik Isaak Nyutonning qabrida uning ilmiy yutuqlari madh etilgan. Ba’zi epitafiyalar hazil yoki kinoya shaklida yozilib, insonning hayotga bo’lgan o’ziga xos qarashini ifodalagan",
