    "title": "Erkli Malikboyeva",
    "category": "Adabiyot",
    "body": "(1928 –2013) U 1950-yili Toshkent teatr va rassomlik sanʼati institutini tugatgan. 1949-yildan Hamza teatri (hozirgi Oʻzbek milliy akademik drama teatri)da ish boahlagan. Ijodining dastlabki yillari mumtoz va zamonaviy dramaturgiyada chuqur lirik obrazlar – Ofeliya (“Gamlet”), Sarvinoz (“Sevgi afsonasi”), Nazira (“Ogʻriq tishlar”), Xannyan (“Sabr kosasi”) va boshqalarni mahorat bilan ijro etdi. Umesh (“Gang daryosining qizi”), Umar (“Jazoir mening Vatanim”) kabi oʻgʻil bolalar obrazida ijodining yangi qirralari ochildi",
