    "body": "Yaponiyaning eng mashxur ramziy, turistik maskanlaridan biri. Sinto e’tiqodidagilar uchun muqaddas tog’ hisoblanadi. Vulqon balandligi 3776 metr. Cho’qqisiga chiqish uchun ob- havoga qarab 4-8 soatgacha vaqt ketasi. Fudzini ko’rish uchun yiliga 300 mingdan ziyod sayyoh tashrif buyuradi. Qadimda samuraylar bu tog’da o’z mashg’ulotlarini o’tkazishgan. Fudzi vulqoni faol hisoblansada, 1707-yildan buyoq aholini bezovta qilmagan. XIX asrga qadar tog’ga ayollarning ko’tarilishi ta’qiqlangan. Bu ishni ilk amalgan oshirgan ayol ledi Fenni Parks bo’lgan(1867)",
