    "category": "Tabiat",
    "body": "— Bu Yaponiyada mashhur bo’lgan ammo juda xavfli bo’lishi mumkin bo’lgan nafis taom. Ushbu baliq tetrodotoksin deb nomlangan o’ta zaharli moddani o’z ichiga oladi, bu esa noto’g’ri tayyorlanganda inson uchun o’limga olib kelishi mumkin. Zaharli qismlari – jigari, terisi va ichki a’zolari tetrodotoksinga boy. Tetrodotoksin ta’siri – mushaklarning falajlanishi, nafas olishning to’xtashi va o’limga olib kelishi mumkin. Ba’zi yaponlar fugu iste’mol qilishni hayajonli tajriba deb hisoblaydilar. Fuguning ta’mi ko’p odamlar tomonidan nihoyatda nozik va yoqimli deb tasvirlanadi",
