    "body": "ya’ni internet brauzer protokolida mijozlar tomonidan qilingan turli xatolargan quyidagi 3 raqamli kodlar bilan javob beriladi. Quyida ulardan bir qanchasi haqida ma’lumotlar keltirilgan. 400 Bad Request («Noto’g’ri, aniq bo’lmagan so’rov») 401 Unauthorized («Ruxsat berilmagan») 402 Payment Required («To’lov talab qilinadi») 403 Forbidden («Taqiqlangan») 404 Not Found («Topilmadi») 405 Method Not Allowed («Ruxsat berilmagan usul») 406 Not Acceptable («qabul qilinmaydi») 407 Proxy Authentication Required («Proksi id talab qilinadi») 408 Request Timeout («so’rov muddati tugagan») 409 Conflict («Mojaro») 410 Gone («O’chirildi») 411 Length Required («Uzunlik talab qilinadi») 412 Precondition Failed («Noto’g’ri shart») 413 Payload Too Large («Juda katta hajm») 414 URI Too Long («URi judayam uzun») 415 Unsupported Media Type («Nomutonosib Media turi») 416 Range Not Satisfiable («Qoniqarsiz zona») 417 Expectation Failed («Kutish amalga oshmadi») 418 I’m a teapot («Men choynakman») 419 Authentication Timeout («Vaqt tugadi») 421 Misdirected Request («Noto’g’ri yo’naltirilgan talab») 422 Unprocessable Entity («Ishlov berilmaydigan obyekt») 423 Locked («Qulflangan») 425 Too Early («Juda erta») 426 Upgrade Required («Yangilash talab qilinadi») 428 Precondition Required («Zaruriy shart») 429 Too Many Requests («Juda ko’p so’rov») 431 Request Header Fields Too Large («Sarlavha maydoni juda katta») 449 Retry With («qayta urunib ko’ring») 451 Unavailable For Legal Reasons («Yuridik sabablarga ko’ra mavjud emas») 499 Client Closed Request («Mijoz talabni yopdi»)",
    "source": "Zakovat Ensiklopediya, I tom, PDF sahifasi 42",
