    "category": "Psixologiya",
    "body": "bu iste’molchilar qisman o’zlari yaratgan mahsulotlarning qiymatini koʻproq qadrlashlari va qimmatroqqa baholashlaridir. Bu nom mebel ishlab chiqaruvchi IKEA kompaniyasi bilan bog’liq. Psixolog Maykl Norton o’z hamkasblari bilan birgalikda “Mijozlar yig’ishni talab qiladigan mahsulot uchun ko’proq pul to’laydilarmi?” - degan fundamental savolga asoslangan tajriba o’tkazdi. Tadqiqot ishtirokchilari origami figuralarini yasash, Lego va IKEA qutilarini yigʻishdan iborat uch xil tajribalarda ishtirok etishdi. Natijalar shuni ko’rsatdiki, odamlar ma’lum bir mahsulotni yig’ishda bevosita ishtirok etganda (hatto u yomon bajarilgan bo’lsa ham) bu mahsulot ular uchun qimmatli boʻlib qoladi",
