    "title": "JAN-POL MARAT",
    "category": "Tarix",
    "body": "(Jean-Paul Marat, 1743–1793) Jan-Pol Marat — Fransuz inqilobi davrida xalq tarafini olgan eng radikal siyosiy arboblardan biri. U “Xalq do’sti” (L’Ami du peuple) nomli gazeta chiqargan va unda qirollikka, zodagonlarga hamda korrupsiyaga qarshi keskin maqolalar yozgan. Marat 1793-yil 13-iyul kuni o’z vannasida pichoqlab o’ldirilgan. Uni Sharlotta Kordé ismli ayol o’ldirgan — u Maratni “xalqni qon to’kishga undayotgan” shaxs deb bilgan. Marat teri kasalligi tufayli ko’p vaqtini issiq vannada o’tkazgan. Shu sababli uning o’limi “vannadagi inqilobchi” nomi bilan tarixda qoldi. Mashhur rassom Jak Lui David uning jasadini tasvirlab, “Maratning o’limi” (La Mort de Marat) nomli asarni yaratgan — bu rasm bugun ham inqilob timsoli sifatida tanilgan",
