    "body": "(Жеводанский зверь) Fransiyaning janubidagi tarixiy Жеводан, hozirgi Лозер departamentiga 1764–1767 yillarda dahshat solgan sirli, bo’riga o’xshash mavjudotdir. Uch yil davomida 100 dan ortiq tasdiqlangan hujum sodir etilgan bo’lib, taxminan 100–124 kishi halok bo’lgan. O’zining g’ayrioddiy kattaligi va xatti-harakati bilan ajralib turgan bu jonzot Fransiya tarixidagi eng mashhur sirli voqealardan biriga aylangan va gigant bo’ridan tortib odamlar tomonidan ataylab o’rgatilgan yirtqichgacha bo’lgan turli afsona hamda nazariyalarni keltirib chiqargan. Bir necha muvaffaqiyatsiz urinishlardan so’ng 1767 yil 19 iyunda mahalliy dehqon Jan Shastel tomonidan otib o’ldirilgan",
