    "category": "Musiqa",
    "body": "1938–1939 yillarda natsistlar zulmi ostida qolgan minglab bolalarni qutqarish uchun maxsus operatsiya amalga oshirildi. Bu operatsiya Kindertransport deb atalgan. 1938-yilda Adolf Gitler siyosati tufayli yahudiylarga qarshi ta’qib kuchaydi. Shu sababli Britaniya hukumati bolalarni qabul qilishga rozi bo’ldi. Asosan Germaniya, Avstriya va Polsha hududlaridan bolalar olib chiqildi. Jami taxminan 10 000 nafar bola qutqarilgan. Ular poyezd va kemalar orqali Buyuk Britaniyaga olib kelingan. Ser Nicholas Winton 669 nafar bolani shaxsan qutqarishga yordam bergan. Uni keyinchalik “Britaniyalik Shindler” deb atashgan. Kindertransport minglab bolalarning hayotini saqlab qolgan va insonparvarlik tarixidagi eng muhim qutqaruv operatsiyalaridan biri hisoblanadi",
