    "category": "Psixologiya",
    "body": "Bu yopiq yoki tor joylarda bo’lishdan kuchli qo’rquv hissi. Bu holat odamda lift, samolyot, yoki derazasiz xonalarda paydo bo’lishi mumkin. Klaustrofobiyadan aziyat chekayotganlar yurak urishi tezlashishi, nafas qisishi yoki vahima xurujini boshdan kechirishadi. Klaustrofobiya atamasi birinchi marta 1879-yilda fransuz psixiatori Benjamin Ball tomonidan fobiyalarni tasniflash doirasida ishlatilgan. U bu atama bilan tor va yopiq joylarda paydo bo’ladigan irratsional qo’rquvni ifodalagan",
