    "title": "Kobra effekti",
    "category": "Tarix",
    "body": "Muammoni hal qilish uchun qabul qilingan yechim aksincha, uni yanada ogʻirlashtiradigan holatni ifodalaydi. Hindistonda Britaniya mustamlakachiligi davrida zaharli kobralarni yoʻq qilish uchun har bir oʻldirilgan ilon uchun mukofot tayinlanadi. Dastlab ilonlar soni kamayadi, biroq odamlar mukofot uchun kobralarni sunʼiy ravishda koʻpaytira boshlaydi. Mukofot bekor qilingach, yetishtirilgan ilonlar yovvoyi tabiatga qoʻyib yuboriladi va natijada kobralar soni yanada oshib ketadi",
