    "title": "Koko Shanel (1883-1971)",
    "category": "Boshqa",
    "body": "Zamonaviy ayollar modasining asoschilaridan biri. 1883-yilda Fransiyada dunyoga kelgan. Kambag’al hayotga qaramay, o’z mehnati va didi bilan butun dunyoni zabt etdi. Ayollar uchun korsetsiz, qulay liboslar, shimlar va erkaklar uslubidagi kiyimlarni ommalashtirdi. U yaratgan “kichik qora ko’ylak” va Chanel №5 atiri moda tarixiga abadiy kirgan. 1920-yillardan boshlab u ayollarning o’ziga bo’lgan ishonchini oshirib, go’zallik me’yorlarini o’zgartirdi. Uning falsafasi oddiy edi: “Hashamat – bu qulaylikdir. Aks holda u hashamat emas.” Shanel brendi esa bugungi kungacha o’z ahamiyatini yo’qotmagan",
