    "title": "Korsakov sindromi",
    "category": "Psixologiya",
    "body": "rus psixiatri Sergey Korsakov tomonidan aniqlangan amnestik sindrom yoki organik amnestik sindromning bir turi. Bu sindrom B1 vitamini yetishmasligi yoki miya shikastlanishi tuyfali yuzaga kelishi mumkin. Bunda, asosan, xotira buziladi. Bemor hozirgina boʻlib oʻtgan voqea-hodisalarni eslay olmaydi, aksincha, yillar ilgari boʻlib oʻtgan voqealarni xotirasida saqlab qoladi. U qayerda turganini, vaqt, sana, atrofidagi kishilarni ismni toʻgʻri aytib berolmaydi. Oʻzi yashab turgan xonasi va joyini adashtiradi, bir daqiqa oldin aytgan soʻzlarini darrov yodidan chiqarib qoʻyadi. Bemorning bilim darajasi, malakasi, kasb-mahorati saqlanib qolgan holda, yangi narsalarni oʻzlashtira olmaydi. Soxta xotira, tez charchash va lohaslik alomatlari kuzatiladi. Korsakov sindromi shuningdek yuqumli kasalliklar, zaharlanish va alkogolizm natijasida ham yuz berishi mumkin",
