    "body": "(fr. craquelure) — rassomlik asari yuzasida vaqt o’tishi bilan paydo bo’ladigan mayda yoriqlar tarmog’i. Asosan: moybo’yoqli rasmlar, laklangan yog’och buyumlar va boshqa san’at asarlarida uchraydi. Sababi: bo’yoq, grunt va lak qatlamlarining vaqt o’tishi bilan qurishi, qisqarishi va harorat/namlik o’zgarishlariga turlicha javob berishi. Ko’rinishi: yuzada o’rgimchak to’riga o’xshash mayda chiziqlar hosil qiladi. San’atshunoslikda ahamiyati: krakelyurning turi va shakli asarning yoshi, saqlanish sharoiti va restavratsiya tarixini aniqlashda yordam berishi mumkin. Muhim: krakelyurning o’zi asarning qadimiyligini mutlaq isbotlamaydi, chunki sun’iy ravishda ham hosil qilish mumkin. Termin: craquelure → fransuzcha craqueler — «yorilmoq, darz ketmoq»",
