    "body": "1865-yildan AQSh da faoliyat yuritib kelayotgan, irqchilik, qora tanlilarga mutloq nafrat va oq tanli aholi ustunligini kuch ishlatib ta’minlash g’oyalarini targ’ib qiluvchi terroristik tashkilot. Jamiyatni fuqarolar urushida magʻlub bo’lgan sobiq askarlar tashkil qilgan. Nomi yunoncha Kuklos(doira), lotincha Cucullus(kapyushon) yoki qurolni qayta o’qlash tovushiga qiyoslanishidan kelib chiqqan, degan versiyalar bor. KKK harakatlaridan oldin ogohlantirish sifatida bargli eman novdasi, qovun yoki apelsin urug’larini yuborgan. Ogohlantirish olgan shaxs oʻz qarashlaridan voz kechishi yoki mamlakatni tark etishi, aks holda u hayotidan mahrum qilinishi mumkin bo’lgan",
