    "title": "Ledi Makbet effekti",
    "category": "Psixologiya",
    "body": "(shuningdek Pontiy Pilat sindromi deb ham ataladi) – psixologik hodisa bo’lib, u inson psixikasidagi aqliy va jismoniy poklik o’rtasidagi bog’liqlikni ifodalaydi. Sharmandalik va vijdon azobi tuyg’usini boshdan kechirgan odam gunohlarini yuvib ketkazishga intiladi. Effekt Uilyam Shekspirning Makbet pyesasi qahramoni Ledi Makbet sharafiga nomlangan. Asarda u qotillik sodir etganidan keyin qo’llaridagi qon dog’larini ko’rib, “Yo’qol, la’nati dogʻ!” – deb xitob qiladi. Makbet effekti tadqiqotchi psixologlar Chjun Chenbo va Kati Lilenkvist tomonidan psixologik tajribada kashf etilgan va ular tomonidan 2006-yilda “Science” jurnalida chop etilgan maqolada tasvirlangan. Keyinchalik Chenbo va Lilenkvist eksperimental ravishda jismoniy va axloqiy poklik o’rtasidagi boshqa aloqalarni ham kashf etdilar. Bir qator tadqiqotlarga asoslanib, ushbu olimlar jamoasi psixologiyaga “axloqiy tozalash” tushunchasini kiritdilar. Quyidagi rasmda avstriyalik rassom Gabriel fon Maks ko’ylagi bilan qo’lini tozalashga urinayotgan Makbet xonimni tasvirlagan",
