    "body": "Bu inson uzoq vaqt davomida rangli tasvirlarga qaragandan so’ng, neytral (oq- qora) tasvirlarda ham rang effektini sezishi bilan tavsiflanadigan psixologik hodisa. Ushbu vizual illyuziya ong osti darajasida idrokning o’zgarishini ko’rsatadi va ba’zan kunlar yoki haftalar davomida saqlanib qolishi mumkin. Makkalou effekti 1960-yillarda amerikalik psixolog Selina Makkalou tomonidan kashf qilingan. U rang va naqshlarning birga taqdim etilishi odamlarning ko’z va miyada qanday iz qoldirishini tajriba orqali aniqlagan",
