    "title": "Mandela effekti",
    "category": "Psixologiya",
    "body": "ayrim hollarda bir qancha odamlar mayda detallarigacha bir xil bo’lgan yolg’on xotiraga ega bo’lishlari mumkin. Bu xotiralar real voqelikka zid hamda uni isbotlovchi hech qanday dalillarsiz bo’ladi. Aynan shu holatga nisbatan “Mandela effekti” termini ishlatiladi. Effektning paydo bo’lish tarixi 2013-yilga borib taqaladi. Shu yilning 5-dekabrida JARning sobiq prezidenti, mashxur siyosiy arbob Nelson Mandela vafot etadi. Bu haqidagi xabar ijtimoiy tarmoqlarda qizg’in muhokama qilinadi. Qiziqarli tomoni, ko’plab foydalanuvchilar ushbu xabardan hayratga tushadilar. Negaki ular siyosatchini o’tgan asrning 80-yillarida qamoqda vafot etgan deb bilishardi. Hattoki ayrimlar bu haqida xabarlar chiqqanini ham eslab o’tadi. Aslida Mandelaning 90-yillarda ozod qilinganini juda kam odam yodga oladi. Mazkur “yolg’on xotira”ni tushuntirish uchun keyinchalik Fiona Brum “Mandela effekti” terminini taklif qiladi",
