    "category": "Adabiyot",
    "body": "Leonardo da Vinchining eng mashhur freska, ya’ni devorga chizilgan rasmlaridan biri. Iso Masih o’z shogirdlari bilan oxirgi kechki ovqatni yeb o’tirgan payt, xususan, ulardan biri — Iuda xiyonat qilishini aytgan dramatik lahza tasvirlangan. Leonardo Iudaning qo’lida kichkina hamyonchasi bilan tasvirlaydi. Ehtimol, bu Isoga xiyonat qilgani uchun olgan 30 kumush tangasi yoki xazinachi sifatida o’n ikki havoriylar orasida tutgan o’rniga ishora qilgan. Shogirdlar soni 12 nafar, ammo rasmda qo’llar soni 26 ta — bu esa 1 juft qo’l ortiqcha degani. San’atshunoslar bu qo’l kimga tegishli ekanini aniqlay olishmagan",
