    "body": "nazariyaga koʻra Motsart musiqasini eshitish, insonda vaqtinchalik IQ darajasini oshiradi. Ayniqsa inson yoshligidan kompozitor asarlarini eshitsa insonning tafakkuri va aqliy rivojlanishiga foydali taʼsir koʻrsatadi. Ushbu nazariya boʻyicha ilk tadqiqotlar 1993-yil Frensis Rausher, Gordon Shou va Ketrin Ki tomonidan olib borilgan. Ular 36 ta talabani uch guruhga boʻlib ay kyu test olishadi. Birinchi guruh talabalariga Motsartning ikkita fortepiano uchun yozilgan re major sonatasi, ikkinchi guruhga xech qanday musiqa qoʻyilmaydi, uchinchi guruh talabalariga esa tinchlantiruvchi, sokin musiqa qoʻyib beriladi. Natijalar shuni koʻrsatadiki, Motsart asarini eshitib test ishlagan talabalar eng yuqori koʻrsatgichni qayd etishgan boʻlib, ushbu samaradorlik faqat kichik muddat (10-15 daqiqa) davom etgan",
