    "body": "doimo beg’ubor bola bo’lib qolish istagi katta odamlarning voqelikni to’g’ri va jiddiy qabul qila olmasliklari natijasida yuzaga keladi. Hayoti davomida hech bo’lmaganda 1 marotaba “Qaniydi yoshligimga qaytib qolsam edi,buncha muammo va g’am tashvishlar bo’lmagan bo’lardi” deydiganlar talaygina. Psixologlar buni “kassallik”ni “Piter Pen sindromi” deb atashadi. Bu holatda odam katta bo’lishdan, o’ziga buror bir mas’uliyatni olishdan qo’rqadi va bulardan qochadi. Bu termin birinchi bora 1983-yilda “O’sib ulg’aymagan erkaklar” kitobida qoʻllaniladi. Baʼzi manbalarda bu sindromni ilk bor Yaponiyada o’z maoshlaridan qoniqmayotgan ofis hodimlari orasida tarqalgani keltirib o’tiriladi",
    "source": "Zakovat Ensiklopediya, I tom, PDF sahifasi 83",
