    "category": "Tarix",
    "body": "(Polycrates) Miloddan avvalgi VI asrda Samos orolini boshqargan yunon hukmdori. U kuchli dengiz floti tuzib, Egey dengizidagi eng qudratli hukmdorlardan biriga aylangan. “Polikrat uzugi” haddan tashqari omadning oxiri yaxshi tugamaydi. Rivoyatga ko’ra, Misr fir’avni Amasis Polikratning uzluksiz omadidan xavotirlanib, unga eng qadrli narsasidan voz kechishni maslahat beradi. Polikrat qimmatbaho uzugini dengizga uloqtiradi. Bir necha kun o’tgach, baliqchi tutgan baliqning qornidan o’sha uzuk topiladi. Bu hodisa “taqdirdan qochib bo’lmaydi” degan alomat sifatida talqin qilinadi. Ko’p o’tmay Polikrat dushmanlari tomonidan hiyla bilan qo’lga olinadi va qatl etiladi",
