    "body": "(Прожектор) effekti – bu insonning xatti-harakatlari va tashqi ko’rinishi boshqalar eʼtiborida ekanligini ortiqcha baholash tendensiyasidan iborat bo’lgan psixologik effekt. “Прожектор” effektining ma’nosi shundaki, odamning tashqi ko’rinishi va uning harakatlarining ko’rinishi o’z-o’zidan bo’rttiriladi, go’yo yorug’lik nuri bilan yoritilgandek. Boshqacha qilib aytganda, biz har doim oʻzimizni diqqat markazida deb o’ylaymiz. Bu ta’sirni birinchi bo’lib amerikalik psixolog Tomas Gilovich payqagan va o’rgangan. Keyinchalik, Uilyams kollejining (AQSh) professori Kennet Savitskiy bilan birgalikda bu tasirga “Прожектор” effekti nomini berishgan",
