    "body": "1895-yilda olmon fizigi Vilgelm Rentgen tasodifan ko’rinmas nurlanishni kashf etdi. U bu nurlar turli jismlar orqali o’tib, faqat suyak kabi zich tuzilmalar tomonidan to’silishini aniqladi. Natijada, inson tanasining ichki tuzilishini aks ettiruvchi tasvirlarni olish imkoni paydo bo’ldi. Dastlabki rentgen surati – bu olim rafiqasining kafti edi. O’z qo’lining rentgen suratini ko’rgan ayol «Men o’z o’limimni ko’rdim!» deya baqirib yuborgan ekan. Rentgen o’z apparatini nemischa X-strahlen-strahlen, ya’ni «Noma’lum nur» deb atagan. Bu yangiligi uchun Nobel mukofotiga loyiq ko’rilgan",
