    "body": "bir xil obyektlar qatoridan ajralib turgan bir obyektning boshqalariga nisbatan yaxshiroq eslab qolinishi. Nazariya 1933-yilda nemis psixiatri va pediatri Xedvig Restorff tomonidan eksperimental ravishda kashf etilgan va uning sharafiga nomlangan. Tajriba davomida Restorff ishtirokchilarga so’zlar ro’yxatini taqdim etgan va ular orasida boshqa soʻzlarga nisbatan farq qiladigan bir nechta so’zlar ham bor edi. Natijalar shuni ko’rsatdiki, ishtirokchilar tajriba oxirida aynan farq qiluvchi soʻzlarni yaxshi eslab qolishgan. Restorff effekti teskari ta’sirga ham ega. Agar siz ma’lum bir so’zni ta’kidlasangiz, u sizning e’tiboringizni jalb qiladi va natijada qolgan so’zlar yomonroq esda qoladi. Restorff effektidan marketing sohasida, dizaynda, xotirani rivojlantirishda, chet so’zlarni o’rganishda va boshqa koʻplab sohalarda foydalanish mumkin",
