    "body": "XIX asrda Pasxa orolidan topilgan sirli yozuv tizimi. Haligacha undagi har bir detal alohida so’zni yoki bo’g’inni anglatishi haqida aniq to’xtamga kelinmagan. Yozuvlarning barchasi toromiro daraxti poyasiga yozilgan. Hozirda dunyo muzeylarida 25 ta shunday yozuvli yog’och bo’laklari saqlanadi. Ularda tahminan 8000 ga yaqin iyerogliflari aniqlangan. Pasxa oroli aholisining asosiy ishga yaroqli qismi 1862-yildan boshlab Peruga qul qilib olib ketilgan. 1864-yil 2-yanvar kuni orolga kelgan rohib Yevgeniy Eyro o’z maktubida orol aholisi har birini uyida o’ziga xos yozuvli yog’och bo’lagi borligi, lekin aholi orasida savodlilari qolmagani uchun ushbu yozuvni o’qish imkoni deyarli mavjud emasligi haqida yozadi",
