    "category": "Mifologiya",
    "body": "1947-yilda AQShning Nyu-Meksiko shtatidagi Roswell shahri yaqinida yuz bergan va keyinchalik NUJ (UFO) hamda o’zga sayyoraliklar haqidagi eng mashhur afsonalardan biriga aylangan voqea. Sana: 1947-yil iyul. Joy: Roswell, New Mexico, AQSh. Fermer W. W. “Mac” Brazel fermasida g’alati qoldiqlar topilgan. 8-iyul 1947 kuni Roswell Army Air Field qoldiqlarni olib qo’ygani haqida matbuot xabari tarqalgan. Keyin AQSh harbiylari bu materiallar meteorologik shar bilan bog’liq ekanini bildirgan. Keyingi o’n yilliklarda esa hodisa “o’zga sayyoralik kemasi qulagan va hukumat jasadlarni yashirgan” degan nazariya bilan mashhur bo’ldi. AQSh hukumatining keyingi izohiga ko’ra, qoldiqlar Project Mogul — Sovet yadroviy sinovlarini aniqlash uchun ishlatilgan maxfiy balon tizimi bilan bog’liq bo’lgan. Muhim: Roswellda alien kosmik kemasi yoki o’zga sayyoralik jasadlari topilgani haqida ishonchli ilmiy dalil mavjud emas. Roswell hodisasi asosan UFO folklori va konspiratsiya madaniyatining mashhur ramziga aylanga",
