    "body": "Fransiya tarixidagi eng mashhur jallodlardan biri. U Fransuz inqilobi davrida Parijning bosh jallodi bo’lgan.1792–1794-yillarda gilotina orqali minglab hukmlarni ijro etgan. Qirol Lyudovik XVIning qatlini ham aynan Sanson amalga oshirgan. U aslida jallodlar sulolasining vakili bo’lib, oilasi bu kasbni bir necha avlod davomida bajargan. U Mariya- Antuanettani ham qatl etgan",
