    "category": "Boshqa",
    "body": "Odatda ayollar va ozchilik guruh vakillarining yuqori lavozimga chiqishiga, ezilgan demografiyaning iyerarxiyasida maʼlum darajadan oshib ketishiga toʻsqinlik qiladigan koʻrinmas toʻsiqni ifodalash uchun ishlatiladi. Shisha shift garchi koʻrinmas toʻsiqni ifodalangan boʻlsa-da, aslida u yengish qiyin boʻlgan holatdir. Bu metafora birinchi marta feministlar tomonidan yuqori natijalarga erishgan ayollarning martabaga erishishlarida toʻsiqqa uchrash holatlariga nisbatan ishlatilgan. Uni 1978-yilda Merilin Loden nutqi chogʻida qoʻllagan",
