    "category": "Boshqa",
    "body": "ruhlar mavjudligi va ular bilan aloqa qilish mumkinligi haqidagi diniy-falsafiy ta’limot va harakat. Asosiy shakllanish davri: XIX asr, ayniqsa 1850-yillar. Asosiy shaxs: Allan Kardec (1804–1869), asl ismi Hippolyte Léon Denizard Rivail. Mamlakat: Fransiya. Kardec spiritizmga oid ta’limotni ruhlar bilan muloqot qilish tajribalari va yozib olingan javoblar asosida tizimlashtirgan. Asosiy g’oya: insonning ruhi o’limdan keyin ham mavjud bo’ladi va reinkarnatsiya orqali rivojlanishda davom etadi. Uning eng mashhur kitobi — Le Livre des Esprits (The Spirits’ Book), 1857-yil. Keyingi muhim asari — The Mediums’ Book (1861). Spiritizm ≠ oddiy “ruh chaqirish” Spiritizmda ruhiy rivojlanish, axloq va reinkarnatsiya markaziy o’rinda turadi. Seans, mediumlik va ruhlar bilan aloqa qilish esa uning amaliy tomonlaridan biridir. Ilmiy nuqtai nazardan: ruhlar bilan aloqa yoki reinkarnatsiya mavjudligini tasdiqlovchi ishonchli ilmiy dalillar mavjud emas. Spiritizm diniy-falsafiy e’tiqod sifatida qaraladi",
