    "body": "bu ijtimoiy fenomen bo’lib, ma’lum bir ma’lumotni jamoatchilik e’tiboridan olib tashlashga urinish (senzura) uning yanada keng tarqalishiga olib keladi (odatda Internet orqali). 2003-yilda Barbara Streyzand o’z uyining fotosurati Kaliforniya qirg’og’ining boshqa fotosuratlari orasida mavjud bo’lgani uchun fotograf Kennet Adelman va Pictopia.com saytidan 50 million dollar talab qilib, sudga murojaat qiladi. Barbaraning advokatlari sudga murojaat etishidan oldin, 3850- raqamli fotosurat (unda Streyzandning uyi ko’rsatilgan) veb-saytdan atigi 6 marta ko’chirilgandi - ikki martasi advokatlar tomonidan. Keyinchalik, jurnalist Pol Rojers (San-Jose Mercury News) sud jarayoni to’g’risidagi ma’lumotlarning tarqalishi natijasida ushbu uyning fotosurati bir oydan keyin 420 mingdan ziyod marta ko’rilganligini ta’kidlaydi. > 2004-yil 10-mayda sud Barbara Streyzandning da’vosini rad etadi",
