    "category": "Boshqa",
    "body": "Kurashchi oʻz raqibini dumaloq ringdan tashqariga chiqarishga yoki oyoq kaftidan boshqa istalgan tana aʼzosi bilan yerga tegizishga (odatda uloqtirish, itarib yuborish) majburlashi mumkin boʻlgan raqobatbardosh toʻliq kontaktli kurash turidir. Eng yuqori unvon “yokozuna” deb ataladi. Sumochilarning kiyimi bo’lgan mavasi esa uzunligi 9 metrgacha bo’ladi. Sumochilar maktabi xeya deb ataladi. Sumochilarga avtomobil haydash ta’qiqlangan. Qizig’i shuki, Yaponiyadagi eng mashxur sumochilar – bu mongollar. Sababi yosh yaponlarda sumo bilan shug’ullanishga qiziqish kamaymoqda",
