    "body": "Indoneziyaning Sumbava orolida joylashgan faol stratovulqon. 1815-yil 10–11- aprel kunlari sodir bo’lgan portlash — insoniyat tarixida qayd etilgan eng kuchli vulqon otilishi hisoblanadi. Portlash natijasida vulqon balandligi 4300 metrdan 2850 metrgacha qisqarib, ulkan krater hosil bo’lgan. Jangdek dahshatli bu portlash oqibatida 100 mingga yaqin odam halok bo’lgan. Atmosferaga chiqib ketgan kul va oltingugurt Yerning iqlimiga kuchli ta’sir ko’rsatgan, 1816-yil tarixga “Yozsiz yil” nomi bilan kirgan. O’sha yili Yevropa va Shimoliy Amerikada sovuq, qor va ocharchilik kuzatilgan",
