    "body": "” — Demyen Xerst ijodida 1991-yilda yaratilgan “Tirik inson ongida o’limni anglashning jismoniy imkonsizligi” asari 4,3 metr uzunlikdagi yo’lbars akulasi bo’lib, u formaldegid to’ldirilgan maxsus idishda saqlanadi. Asar 1991- yilda kolleksioner Charlz Saatchi tomonidan buyurtma qilingan. U Demyen Xerstga: “Nimani xohlasang, o’shani yarat” degan. Asarni yaratish 70 000 dollardan ortiq mablag’ talab qilgan — akula maxsus buyurtma bilan Avstraliyada tutilgan, bundan tashqari kimyoviy saqlash jarayoni ham juda qimmatga tushgan. Ko’pchilik uchun jirkanch ko’ringan ushbu asarda “Odam o’limni ko’rishi, lekin uni anglay olmasligi” tasvirlangan",
