    "title": "Timsoh koʻz yoshlari",
    "category": "Tarix",
    "body": "Koʻp tillarda mavjud boʻlgan frazeologik birlik boʻlib, his-tuygʻularning soxta, samimiy boʻlmagan ifodasini, soxta yigʻlashni anglatadi. Bu ibora timsohlar oʻljasini tanovul qilayotganda yigʻlaydi, degan qadimgi ishonchdan kelib chiqqan. Plutarx asarlaridan birida timsohning xatti-harakati kimnidir oʻldirishga qasd qilib, keyin qurboniga motam tutadigan odamlarning qilmishiga qiyoslanadi. Timsoh koʻz yoshlari sindromi yoki Bogorad sindromi Bell falajini notoʻgʻri davolash natijasida paydo boʻlgan, oqibatda ovqatlanish paytida yosh bezlari taʼsirlanadi. Sovet neyrofiziologi F. A. Bogorad birinchi marta 1928-yilda sindromni tasvirlab berdi va ushbu nomni taklif qilgan",
