    "title": "Trevi favvorasi",
    "category": "Geografiya",
    "body": "Trevi favvorasi (italyancha: Fontana di Trevi) — Rim, Italiyada joylashgan mashhur barokko uslubidagi favvora. Favvora 1732–1762 yillarda Nikolò Salvi tomonidan loyihalashtirilgan. Uning balandligi 26,3 metr, kengligi esa 49,15 metr bo’lib, Rimdagi eng yirik barokko favvoralardan biridir. Favvoraning markazida dengiz xudosi Okean haykali joylashgan, atrofida ikki yirik atlant va turli dengiz hayvonlari tasvirlangan. Favvoraga tashrif buyurganlar odatda orqa tomonga o’tirib, tanga tashlab, Rimga qaytishlarini yoki tilaklarini amalga oshirishadi",
