    "category": "Texnologiya",
    "body": "bu yapon robototexnika olimi va muhandisi Masahiro Mori tomonidan ishlab chiqilgan gipotezaga asoslangan hodisa bo’lib, robot yoki boshqa texnikaning, odamga o’xshab ko’rinishi yoki harakatlanishi, kuzatuvchida chuqur nafrat va qo’rquvni keltirib chiqaradi. 1978-yilda yapon olimi Masahiro Mori odamlarning robotlar ko’rinishiga bo’lgan hissiy munosabatini o’rganib, so’rov o’tkazdi. Dastlab, natijalarni oldindan aytish mumkin edi: robot odamga qanchalik o’xshash bo’lsa, u shunchalik yoqimli ko’rinadi — lekin faqat ma’lum bir chegaraga qadar. Maksimal odam ko’rinishiga yaqin robotlar, kutilmaganda odamlarda noqulaylik va qo’rquv hissini keltirib chiqardi. O’rganishlar natijasida, inson psixikasida yuzaga keladigan qattiq tushkun holatning, sxemadagi ko’rinishi, effekt nomlanishiga sabab bo’ldi. Shuningdek, effekt kinomotografiya va rassomchilikda “Giperrealizm” yo’nalishini ajralib chiqishiga turtki bo’ldi",
