    "category": "San’at",
    "body": "Genuyadan unchalik uzoq bo’lmagan San-Fruttuozo buxtasida dengiz tubida joylashgan haykalning nomi. Balandligi 2,5 metr bo’lgan ushbu haykal 1954-yil 22-avgustda 17 metr chuqurlikka o’rnatilgan. Suv ostiga haykal o’rnatish g’oyasi ilk bora italyan dayveri Dulio Markantega suv osti meditatsiyasi bilan shug’ullanayotgan paytda kelgan. U mazkur haykal orqali bu yerda 1947-yilda halok bo’lgan birinchi italyan akvalangisti Dario Gonzatti xotirasini abadiylashtirmoqchi ham bo’ladi. Haykalni Gvido Galleti ismli haykaltarosh yasagan",
