    "title": "Tula",
    "category": "Geografiya",
    "body": "Rossiyaning qadimiy shaharlaridan biri boʻlib o’zining mashhur pryaniklari va samovarlari bilan tanilgan. Tula pryanik - bosma ruscha pryanikning mashhur turi. Odatda, Tula pryanik to’rtburchak kafel yoki tekis shaklga o’xshaydi. Shtamplangan pryanik yasash san’at turi hisoblanadi. Imzolar turli naqshlar, belgilar, Tula Kremlining tasvirlari, ismlar, tabriklarni o’z ichiga olishi mumkin. Tula samovari –an’anaviy choy qaynatish idishi.Ilk samovarchilar rus aka-uka Lisitsinlar Ivan Fyodorovich va Nazar Fyodorovichlar edi. 1778-yilda ular samovar yasadilar va oʻsha yili Nazar Lisitsin Rossiyada birinchi samovar ishlab chiqaruvchi zavodni roʻyxatdan oʻtkazdi",
