    "id": 792,
    "title": "Tyuring testi",
    "category": "Boshqa",
    "body": "Ilk bor Alan Tyuring tomonidan “Mind” jurnalida 1950 -yilda Hisoblash mashinalari va oʻy nomli maqolada ilk bor tilga olingan emperik test. Tyuring mashina ham oʻylashini isbotlashga harakat qiladi. Ushbu testning odatiy talqini quyidagicha: “Inson bir kishi va bir inson bilan muloqot qila oladi. Savollarga berilgan javoblarga asoslanib, u kim bilan gaplashayotganini aniqlashi kerak: odam yoki kompyuter dasturi. Kompyuter dasturining maqsadi esa odamni notoʻgʻri tanlov qilishga undash”. Test qatnashchilari bir-birlarini koʻrmaydilar. Agar qatnashchi suhbatdoshlarning qaysi biri inson ekanini aniq ayta olmasa, dastur sinovdan oʻtgan hisoblanadi",
