    "category": "Boshqa",
    "body": "Janubiy va Sharqiy Afrika xalqlari falsafasiga ko’ra, insonlar o’rtasidagi o’zaro bog’liqlik va insoniylikni ifodalovchi tushuncha. Ushbu atama zulucha “umuntu ngumuntu ngabantu” iborasidan kelib chiqqan bo’lib, “Men borman, chunki biz bormiz” yoki “Inson boshqa insonlar orqali insondir” degan ma’nolarni anglatadi. Ubuntu falsafasining markazida saxovat, hamdardlik, resurslarni baham ko’rish va jamoaviy birlik yotadi. Bu dunyoqarashga ko’ra, bir insonning baxtsizligi yoki kamsitilishi butun jamiyatning shikastlanishi deb qabul qilinadi",
