    "body": "Nomaʼlum uchar jismlar va ular bilan taxminan bogʻliq boʻlgan voqea-hodisalar holatlar haqidagi guvohlarning xabar va maʼlumotlarini toʻplash, guruxlashtirish va talqin qilish, ularning toʻgʻri-notoʻgʻriligini aniqlash bilan shugʻullanuvchi soha. Bu termin ilk bor 1950-yillarda paydo bo’lgan va ilmiy hamda noilmiy qiziqishlar doirasida rivojlangan. Ufologiya bilan shug’ullanuvchi shaxs ufolog deb ataladi. Ufologlar NUO (Noma’lum Uchar Obyektlar) bilan bog’liq hodisalarni o’rganishadi va bu borada guvohlarning ko’rsatmalari, fotosuratlar, videolar, va boshqa dalillarni tahlil qilishadi",
