    "id": 797,
    "title": "Uilyam Gibson",
    "category": "Adabiyot",
    "body": "kiberpank janrining asoschisi Uilyam Gibson 1948-yilda tug’ilgan amerika- kanadalik yozuvchi bo’lib, kiberpank janrining asoschilaridan biri hisoblanadi. 1984-yilda chop etilgan “Neuromancer” romani nafaqat kiberpankni ommalashtirdi, balki “kibermakon” (cyberspace) atamasini ham mashhur qildi. Asarda sun’iy intellekt, xakerlar va virtual olam tasvirlari bugungi internet va raqamli dunyo haqidagi tasavvurlarga katta ta’sir ko’rsatgan. Mashhur asarlari: Neuromancer (1984) Count Zero (1986) Mona Lisa Overdrive (1988) Pattern Recognition (2003) Gibsonning asarlari ilmiy fantastika tarixida muhim o’rin tutadi va zamonaviy texnologiyalar rivojlanishini oldindan tasvirlagan eng ta’sirli adiblardan biri sifatida e’tirof etiladi",
