    "id": 800,
    "title": "Umberto Eko",
    "category": "Adabiyot",
    "body": "(1932–2016) — italiyalik yozuvchi, faylasuf, semiotik, adabiyotshunos va medievalist. U ayniqsa tarixiy detektiv romanlari va belgilar, til hamda talqin haqidagi ilmiy ishlari bilan mashhur. Tug’ilgan: 5-yanvar 1932, Alessandria, Italiya. Vafot etgan: 19-fevral 2016, Milan. Ta’limi: Turin universiteti; 1954-yilda Tomas Akvinskiy estetikasi bo’yicha dissertatsiya himoya qilgan. Asosiy sohasi: semiotika — belgilar, ramzlar va ularning ma’nosini o’rganish. Universitet: 1975-yildan Bolonya universitetida semiotika professori bo’lgan. Eng mashhur asarlari «Atirgul nomi» (Il nome della rosa, 1980) — XIV asr monastirida sodir bo’ladigan qotilliklarni tergov qiluvchi rohib Uilyam Baskervillik haqidagi tarixiy detektiv roman. 1980-yilda Strega mukofotini olgan va 45 dan ortiq tillarga tarjima qilingan. «Fuko mayatnigi» (Il pendolo di Foucault, 1988) — fitnalar, ezoterika va tarixiy sirlar bilan bog’liq roman. «Kecha oldingi orol» (1994) «Baudolino» (2000) «Praga qabristoni» (2010) «Nol raqam» (2015) — uning so’nggi romani. Qiziqarli fakt Eco faqat yozuvchi emas edi. U 40 dan ortiq faxriy doktorlik darajasiga ega bo’lgan va juda katta shaxsiy kutubxona to’plagan. 2021-yilda uning 44 000 jildlik zamonaviy kutubxonasi va arxivi Bolonya universitetiga topshirilgan",
