    "category": "Adabiyot",
    "body": "Vasiliy Vereshagin (1871–1872) Vereshchagin bu asarida urushning dahshatli oqibatlarini ramziy obraz orqali ifodalagan. Kartinaning markazida inson suyaklaridan qurilgan ulkan piramida tasvirlangan. Bu piramida urush qurbonlarining son-sanoqsizligini va insoniyat tarixida takrorlanib kelayotgan fojealarni anglatadi. Rassom yorqin osmon fonida oq suyaklarni chizib, kontrast yaratgan — shu orqali u hayot va o’lim o’rtasidagi keskin tafovutni ko’rsatadi. “Urush apofeozi” nafaqat san’at asari, balki kuchli tinchlik chaqirig’i sifatida ham tarixda o’rin olgan",
