    "title": "Usta va Margarita», Mixail Bulgakov. (1967)",
    "category": "Boshqa",
    "body": "Syujet Voland – ya’ni shayton obrazidagi sirli mehmonning 1930-yillar Moskva hayotiga aralashuvi bilan boshlanadi. U bilan birga kelgan sehrli yordamchilari orqali odamlarning yolg’onchiligi, ochko’zligi va ikkiyuzlamachiligi ochiladi. Bu fon orqasida ikkinchi chiziq — Usta va Margarita sevgisi rivojlanadi. Usta – yozuvchi, o’zining Pontiy Pilat haqidagi romanini yozgani uchun qatag’on qilinadi. Margarita esa o’z sevgilisi uchun jonini ham fido qilishga tayyor. Usta yozgan roman esa uchinchi chiziqni tashkil etadi – unda Pontiy Pilatning haqiqat oldida ojizligi, qo’rquvi va tavbasi tasvirlanadi. Yoshua (Iso) – haqiqat timsoli bo’lib, uni aybsiz bilgan Pilat baribir uni o’limga mahkum qiladi. Bulgakov asarda din, adolat, san’at, muhabbat va erkinlik mavzularini o’zaro bog’lab, insoniyat va jamiyat mohiyatiga teran nazar tashlaydi",
