    "category": "Adabiyot",
    "body": "“Uzuklar Hukmdori” trilogiyasi fantastik adabiyot tarixida inqilob qilgan asarlardan biridir. Asar O’rta Yer deb ataluvchi sehrli dunyoda sodir bo’ladi. Hikoyaning markazida — barchani hukmronlik ostiga oluvchi qudratli Uzuk va uni yo’q qilish uchun qilingan mashaqqatli safar turadi. Asosiy qahramon — oddiy hobbit Frodo Beggins bo’lib, u kuchli yovuzlik — Sauron kuchlariga qarshi turish uchun Uzukni halokat tog’iga olib borib, uning lavasida yo’q qilishi kerak. Frodoning safdoshlari — Sem, Aragorn, Legolas, Gimli, Gendalf va boshqalar — sadoqat, mardlik va do’stlik ramzlari sifatida namoyon bo’ladi. Tolkin O’rta Yer tarixini, tillarini, xalqlarini va madaniyatini o’ziga xos tarzda asarda ochib bera olgan",
