    "body": "(1897–1986) Rus va sovet adabiyotining mashhur yozuvchisi, dramaturg va jurnalisti. Birinchi va Ikkinchi jahon urushlari davrida harbiy muxbir sifatida ishlagan. Uning asarlari bolalar va kattalar orasida keng shuhrat qozongan. Eng mashhur asarlari: “Polk o’g’li” (Сын полка) — urush yillarida ota-onasidan ayrilgan bolaning taqdiri haqida qissa. “Yetti rangli gul” (Цветик- семицветик) — har bir yaprog’i bitta tilakni amalga oshiradigan sehrli gul haqidagi mashhur ertak",
