    "title": "Valkiriya",
    "category": "Mifologiya",
    "body": "Skandinav mifologiyasida jangda halok bo’lgan jangchilarning ruhlarini olib ketadigan, Odinning xizmatidagi jasur ayollar. Ularning asosiy vazifasi jang maydonida halok bo’lgan jangchilarning ruhlarini Valhallaga olib borishdir. Jangchilarni Valhallaga toʻplashdan maqsad esa qiyomat (Ragnarok)dagi ulkan jang vaqtida Odin va Thorning yonida turib, qahramonlarcha jang qiladigan bahodir jangchilarni bir joyga yigʻish hisoblanadi. Valkiriyalar qahramonlik, jasorat, va mardlikni ifodalaydigan obrazlardir",
