    "title": "Van Gog sindromi",
    "category": "Musiqa",
    "body": "bemor o’zini-o’zi operatsiya qilishi yoki muayyan operatsiyani bajarishni talab qilishi bilan namoyon bo’ladi. Sindromning asosiy klinik belgisi - bu o’z-o’zini jarohatlash (tananing ayrim qismlarini kesib tashlash) va/yoki jarrohlik operatsiyalarini bajarishda shifokorlarga doimiy talablar. Ushbu sindromning mashxur rassom sharafiga nomlanishi ham bejiz emas. Versiyalardan biriga ko’ra, Van Gog psixologik muammolarni boshdan kechirayotgan kunlarning birida o’z qulog’ining bir qismini kesib tashlagan. (Boshqa bir versiyada uning qulog’i rassomning yaqin do’sti Pol Gogen tomonidan foxisha Rashel tufayli kelib chiqqan janjal payti kesib yuborilgan deyiladi.) Ushbu sindrom ilk bor 1934-yilda “The Psychoanalytic Quarterly” jurnalida amerikalik psixiatr Karl Menninger tomonidan bayon qilingan",
