    "body": "birinchi oʻzbek kinooperatori va oʻzbek kinosanʼatining asoschisi XX asr oxirida Xorazmning oʻsha paytdagi hukmdori Muhammad Rahimxon II nemis-mennonitlarning bir necha oilasiga oʻlkada yashashiga ruxsat bergan. Ularning eng yoshi ulugʻi Vilgelm Penner yoki mahalliy odamlarning tili bilan Panor buvada qiziquvchan Xudoybergan birinchi marta fotoapparatni koʻrgan va undan foydalanishga ruxsat soʻragan. Keyinchalik Panor buva shogirdining muvaffaqiyatlaridan xursand boʻlib, unga fotoapparatni sovgʻa qilgan. U “Oʻrta Osiyo meʼmoriy yodgorliklari”, “Turkiston koʻrinishlari”, “Xiva va xivaliklar” kabi qisqa filmlarni ishlagan",
