    "title": "Xvasondagi qotilliklar",
    "category": "Tarix",
    "body": "1986 yildan 1991 yilgacha Janubiy Koreyaning Kyongi provinsiyasining Xvason shahrida sodir bo’lgan bir qator qotilliklar. Koreya jinoiy tarixidagi eng mashxur holatlar qatorida jinoyatlar politsiya faoliyatidagi kamchiliklarni fosh qildi. Bong Jun Xoning “Qotillik xotiralari” filmi shu voqeani hikoya qiladi.(2003) Jinoyatlar o’n nafar ayol va qiz Xvasondagi qishloq yo’llaridan o’g’irlab ketilgan, jinsiy tajovuz qilingan va o’z kiyimlari bilan bo’g’ib o’ldirilgani haqida. Qurbonlar 14 yoshli talabadan 71 yoshli kampirgacha bo’lgan. Kuchli jamoatchilik bosimi ostida politsiya 1989 yilda mahalliy Yun Sung Yoni zo’ravonlik orqali majburan tan olganidan keyin qotilliklar uchun hibsga oldi. U 20 yil qamoqda o’tirdi. Haqiqiy qotil Li Chun-Jening identifikatsiyasi 2019-yilda yuqori DNK tex.riga duch kelgach Li 14 ta qotillik va 30 ga yaqin jinsiy tajovuzni tan oldi. Da’vo muddati 2006 yilda tugaganligi sababli, jinoiy javobgarlikka tortilmagan,faqat bir yil davomida qamoqda saqlangan",
