    "title": "Zeygarnik effekti",
    "category": "Psixologiya",
    "body": "Litva-sovet psixologi Blyuma Zeygarnik Kurt Lyuinning ofitsiantlar xaqidagi yozganlarini oʻqib qoladi va bu jarayonni chuqurroq oʻrgana boshlaydi. Kurt Lyuin yozishicha, ofitsiant xali puli toʻlanmagan buyurtmalarni juda yaxshi eslab qolgan, pul toʻlangandan soʻng esa buyurtma xaqida deyarli eslay olmaganligi kuzatilgan. Zeygarnikning ishlari 1927-yilda Psychological Research jurnalida chiqadi. Ushbu effektni asoslashda u yana bir tajriba oʻtkazgan, unga koʻra birinchi gurux talabalarga 10 lab masalalar berishadi va maʼlum vaqt oʻtgach vaqt tugadi deb oxirigacha bajarishga qoʻymaydi, 2-gurux esa oxirigacha bajaradi. Oʻquvchilardan qanday masalalar tushganini soʻrashganda 1-gurux deyarli xammasini eslab qolgan. Demak, Zeygarnik effektiga koʻra, oxiriga yetmagan yoki toʻxtalishlar bilan davom etadigan ishlar inson xotirasida yaxshiroq qoladi. Buni psixologik tomondan shunday tushuntirishadi- shunchaki ish yakuniga yetmagach sizning koʻproq diqqatingiz shunga qaratilgan boʻladi va bunda ushbu ish xotirada yaxshiroq qolishi taʼminlanadi",
    "source": "Zakovat Ensiklopediya, I tom, PDF sahifasi 123",
    "question": "Quyidagi ta’rif qaysi atama, shaxs yoki hodisaga tegishli?",
    "answer": "Zeygarnik effekti",
